    _scenario("PA2a", "P75 6T đầu; sông Đà P90; sau đó P65", 10.20, 391.767, 391.767, 86.636, 12.263, 13.189, 0, [29.106,23.575,31.199,32.412,34.736,35.513,36.356,36.597,34.349,33.667,31.820,32.436], [4.748,3.738,4.052,4.432,5.585,7.464,11.107,12.146,10.821,9.739,7.218,5.586]),
    _scenario("PA2b", "P75 cả năm; sông Đà P90 6T đầu", 10.20, 391.776, 390.781, 81.093, 14.969, 13.007, .995, [29.106,23.576,31.199,32.412,34.736,35.513,36.356,36.597,34.349,33.671,31.822,32.438], [4.748,3.738,4.052,4.432,5.585,7.464,10.371,10.919,9.678,8.713,6.341,5.052]),
