    _scenario("PA3a", "P75 6T đầu; sông Đà P90; sau đó P65", 12.40, 399.601, 399.304, 86.662, 15.917, 13.190, .297, [29.688,24.054,31.823,33.058,35.429,36.220,37.081,37.326,35.034,34.342,32.460,33.086], [4.748,3.738,4.052,4.432,5.611,7.464,11.107,12.147,10.821,9.739,7.218,5.586]),
