BTS = {
    "labels": ["10/2026", "11/2026", "12/2026", "01/2027", "02/2027", "03/2027", "04/2027"],
    "august": [-18, -12, -9, -13, -5, -9, None],
    "september": [-17, -5, 2, -3, -2, -9, -21],
}


def render_analysis_page() -> str:
    data = json.dumps({"months": MONTHS, "scenarios": SCENARIOS, "bts": BTS}, ensure_ascii=False)
    rows = "".join(
        f"<tr><td><b>{s['id']}</b></td><td>{s['growth']:.2f}%</td><td>{s['hydrology']}</td>"
        f"<td>{s['demand']:.3f}</td><td>{s['hydro']:.3f}</td><td>{s['oil']:.3f}</td>"
        f"<td class={'risk' if s['shortage'] else 'ok'}>{s['shortage']:.3f}</td></tr>"
        for s in SCENARIOS
    )
    return f'''<!doctype html>
<html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Phân tích năng lượng và nguồn nước 2027</title>
<style>
:root{{--bg:#f3f7fc;--panel:#fff;--line:#d5e3f5;--text:#082747;--muted:#58708a;--blue:#1665d8;--green:#138a4b;--red:#d33f49}}
*{{box-sizing:border-box}} body{{margin:0;background:var(--bg);color:var(--text);font:14px Arial,sans-serif}} .page{{max-width:1520px;margin:auto;padding:12px}}
.topbar,.band{{border:1px solid var(--line);border-radius:10px;background:var(--panel);box-shadow:0 10px 24px rgba(19,59,103,.06)}} .topbar{{padding:18px 20px}} .band{{margin-top:12px;padding:16px}}
.nav,.section-head{{display:flex;align-items:flex-start;justify-content:space-between;gap:16px}} h1{{margin:0;font-size:25px}} h2{{margin:0;font-size:18px}} h3{{margin:0 0 7px;font-size:14px}}
.subtitle,.note{{margin:6px 0 0;color:var(--muted);line-height:1.45}} .note{{font-size:12px}} .actions{{display:flex;gap:8px;flex:none}}
.btn{{height:36px;display:inline-flex;align-items:center;padding:0 13px;border:1px solid #c6dbff;border-radius:7px;background:#eaf3ff;color:#0b55b7;font-weight:700;text-decoration:none}} .btn.primary{{background:var(--blue);color:#fff}}
.signals{{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-top:14px}} .signal{{min-height:108px;padding:14px;border:1px solid var(--line);border-radius:7px}} .signal span,.kpi span{{color:var(--muted);font-size:10px;font-weight:700;text-transform:uppercase}} .signal strong{{display:block;margin:7px 0 4px;font-size:24px}} .signal p,.timeline p,.decision p{{margin:0;color:#35526e;line-height:1.45;font-size:12px}}
.two-col,.charts{{display:grid;grid-template-columns:1.1fr .9fr;gap:12px;margin-top:12px}} .chart{{height:310px}} .chart canvas{{display:block;width:100%;height:100%}} .timeline{{border-top:1px solid var(--line)}} .timeline>div{{display:grid;grid-template-columns:100px 1fr;gap:12px;padding:12px 2px;border-bottom:1px solid var(--line)}} time{{color:#0b55b7;font-weight:800}}
select{{height:34px;min-width:105px;border:1px solid #c7dcf5;border-radius:6px;padding:0 9px;background:#fff;color:var(--text);font-weight:800}} .kpis{{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin:12px 0}} .kpi{{padding:11px;border:1px solid #e1ebf7;border-radius:7px;background:#f9fbfe}} .kpi strong{{display:block;margin-top:5px;font-size:18px}}
.summary{{color:#35526e;line-height:1.45}} .table-wrap{{overflow:auto;border:1px solid var(--line);border-radius:8px;margin-top:12px}} table{{width:100%;min-width:920px;border-collapse:collapse;font-size:12px}} th,td{{padding:9px 10px;border-bottom:1px solid #e7eef8;text-align:right;white-space:nowrap}} th{{background:#f5f9fe;color:#294d70;font-size:10px;text-transform:uppercase}} th:first-child,td:first-child,th:nth-child(3),td:nth-child(3){{text-align:left}} .ok{{color:var(--green);font-weight:800}} .risk{{color:var(--red);font-weight:800}}
.decision{{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:12px}} .decision article{{padding-right:14px;border-right:1px solid var(--line)}} .decision article:last-child{{border:0}} .sources{{color:#526b84;font-size:11px;line-height:1.55}} .sources p{{margin:5px 0}}
@media(max-width:1000px){{.signals,.kpis{{grid-template-columns:repeat(2,1fr)}}.two-col,.charts,.decision{{grid-template-columns:1fr}}.decision article{{border-right:0;border-bottom:1px solid var(--line);padding-bottom:12px}}}} @media(max-width:620px){{.nav{{flex-direction:column}}.signals,.kpis{{grid-template-columns:1fr}}.chart{{height:260px}}}}
</style></head><body><main class="page">
<header class="topbar"><div class="nav"><div><h1>Phân tích cân bằng năng lượng và nguồn nước 2027</h1><p class="subtitle">Kịch bản El Niño, xu thế KTTV cuối 2026–đầu 2027 và 10 phương án cân bằng điện.</p></div><div class="actions"><a class="btn" href="/">Dashboard hồ</a><a class="btn primary" href="#scenarios">Phương án 2027</a></div></div>
<div class="signals"><article class="signal"><span>Tín hiệu ENSO</span><strong>&gt; 90%</strong><p>Xác suất El Niño rất mạnh theo tài liệu phân tích cung cấp; tiếp tục cập nhật bản tin chính thức.</p></article><article class="signal"><span>Mưa mùa khô</span><strong>-20% đến -40%</strong><p>Kịch bản rủi ro cho Trung Bộ, Tây Nguyên và Nam Bộ trong tài liệu đánh giá.</p></article><article class="signal"><span>BTS tháng 10/2026</span><strong>-17% TBNN</strong><p>Bản tin 15/09 cải thiện nhẹ so với -18% trong bản tin 15/08.</p></article><article class="signal"><span>Phương án tham chiếu</span><strong>PA2a</strong><p>Phụ tải tăng 10,2%; thủy văn thận trọng 6 tháng đầu năm; không thiếu điện năng năm.</p></article></div></header>
<section class="band"><div class="section-head"><div><h2>Xu hướng nguồn nước Buôn Tua Srah</h2><p class="note">Mức tăng/giảm lưu lượng đến hồ so với TBNN trong hai bản tin KTTV.</p></div></div><div class="two-col"><div class="chart"><canvas id="btsChart"></canvas></div><div class="timeline"><div><time>10–12/2026</time><p>Bão/ATNĐ thấp hơn TBNN. Dòng chảy BTS lần lượt -17%, -5% và +2%; tháng 12 cải thiện rõ so với bản tin tháng 8.</p></div><div><time>01–03/2027</time><p>Nhiệt độ Tây Nguyên và Nam Bộ có thời kỳ cao hơn TBNN 1,5–2,5°C. Dòng chảy BTS trung bình -3%, -2% và -9%.</p></div><div><time>04/2027</time><p>Mưa Cao nguyên Trung Bộ phổ biến 80–150 mm nhưng dòng chảy BTS vẫn thấp hơn TBNN 21%.</p></div><div><time>Hàm ý</time><p>Ưu tiên tích nước cuối 2026 và cập nhật cân bằng theo mực nước thực đo; không quy đổi trực tiếp cường độ El Niño thành một tỷ lệ thiếu nước cố định.</p></div></div></div></section>
<section class="band" id="scenarios"><div class="section-head"><div><h2>Cân bằng năng lượng theo phương án</h2><p class="note">Đơn vị TWh; số liệu từ các sheet PA1–PA4a của bảng CBNL năm 2027.</p></div><label>Phương án <select id="scenarioSelect"></select></label></div><div class="kpis"><div class="kpi"><span>Phụ tải</span><strong id="demandKpi"></strong></div><div class="kpi"><span>Thủy điện</span><strong id="hydroKpi"></strong></div><div class="kpi"><span>Nhiệt điện dầu</span><strong id="oilKpi"></strong></div><div class="kpi"><span>Nhập khẩu</span><strong id="importKpi"></strong></div><div class="kpi"><span>Thiếu hụt</span><strong id="shortageKpi"></strong></div></div><p class="summary" id="scenarioSummary"></p><div class="charts"><div class="chart"><canvas id="monthlyChart"></canvas></div><div class="chart"><canvas id="scenarioChart"></canvas></div></div></section>
<section class="band"><h2>So sánh 10 phương án</h2><p class="note">Thiếu hụt là phần chênh âm giữa tổng sản lượng và tổng tải trong bảng nguồn.</p><div class="table-wrap"><table><thead><tr><th>PA</th><th>Tăng tải</th><th>Giả định thủy văn</th><th>Phụ tải</th><th>Thủy điện</th><th>Dầu</th><th>Thiếu hụt</th></tr></thead><tbody>{rows}</tbody></table></div></section>
<section class="band"><h2>Khuyến nghị sử dụng kịch bản</h2><p class="note">Khung ra quyết định, không thay thế phương thức vận hành được phê duyệt.</p><div class="decision"><article><h3>Kịch bản làm việc: PA2a</h3><p>Dùng làm nền khi phụ tải tăng khoảng 10,2% và nguồn nước 6 tháng đầu năm ở mức thận trọng.</p></article><article><h3>Chuyển PA2b hoặc PA3a</h3><p>Rà soát khi mực nước 31/12 thấp hơn kế hoạch, dòng chảy thực đo thấp hơn dải KTTV hoặc tăng tải vượt 10,2%.</p></article><article><h3>PA4a để kiểm tra rủi ro</h3><p>PA4a thiếu 6,493 TWh và huy động dầu 19,840 TWh; dùng kiểm tra sức chịu đựng, không làm dự báo trung tâm.</p></article></div></section>
<footer class="band sources"><h2>Nguồn và giới hạn</h2><p>Bản tin KTTV 7 tháng ngày 15/08/2026 và 15/09/2026; bảng Tổng hợp CBNL năm 2027 ngày 18/08/2026; hai tài liệu phân tích El Niño và phương án vận hành do người dùng cung cấp.</p><p>Các giá trị ENSO, thiếu hụt nước và sản lượng là kịch bản. Trang này tách dữ liệu nguồn, nhận định và khuyến nghị để không thể hiện xác suất khí hậu như kết quả vận hành chắc chắn.</p></footer>
</main><script>
const DATA={data};
const fmt=(v,d=3)=>Number(v).toLocaleString('vi-VN',{{minimumFractionDigits:d,maximumFractionDigits:d}});
const palette={{blue:'#1665d8',green:'#16a34a',gray:'#94a3b8',red:'#d33f49',amber:'#d97706',grid:'rgba(132,165,199,.24)',text:'#49647f'}};
function surface(id){{const canvas=document.getElementById(id),box=canvas.getBoundingClientRect(),dpr=window.devicePixelRatio||1;canvas.width=Math.round(box.width*dpr);canvas.height=Math.round(box.height*dpr);const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);return{{canvas,ctx,w:box.width,h:box.height}}}}
function legend(ctx,items,w){{ctx.font='11px Arial';let x=52;items.forEach(item=>{{ctx.strokeStyle=item.color;ctx.lineWidth=3;ctx.setLineDash(item.dash||[]);ctx.beginPath();ctx.moveTo(x,38);ctx.lineTo(x+24,38);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle=palette.text;ctx.fillText(item.label,x+30,42);x+=Math.min(150,ctx.measureText(item.label).width+65)}})}}
function lineChart(id,labels,series,title,ySuffix=''){{const{{ctx,w,h}}=surface(id),pad={{l:48,r:16,t:58,b:34}};ctx.clearRect(0,0,w,h);ctx.fillStyle='#082747';ctx.font='bold 12px Arial';ctx.textAlign='center';ctx.fillText(title,w/2,17);ctx.textAlign='left';legend(ctx,series,w);const values=series.flatMap(s=>s.data.filter(v=>v!==null));let min=Math.min(...values,0),max=Math.max(...values,0);const margin=Math.max((max-min)*.12,1);min-=margin;max+=margin;const x=i=>pad.l+i*(w-pad.l-pad.r)/Math.max(labels.length-1,1),y=v=>pad.t+(max-v)*(h-pad.t-pad.b)/(max-min);ctx.font='10px Arial';ctx.strokeStyle=palette.grid;ctx.fillStyle=palette.text;ctx.lineWidth=1;for(let i=0;i<5;i++){{const val=min+(max-min)*i/4,yy=y(val);ctx.beginPath();ctx.moveTo(pad.l,yy);ctx.lineTo(w-pad.r,yy);ctx.stroke();ctx.textAlign='right';ctx.fillText(`${{fmt(val,0)}}${{ySuffix}}`,pad.l-7,yy+3)}}labels.forEach((lab,i)=>{{ctx.textAlign='center';ctx.fillText(lab,x(i),h-10)}});series.forEach(s=>{{ctx.strokeStyle=s.color;ctx.lineWidth=2.5;ctx.setLineDash(s.dash||[]);ctx.beginPath();let started=false;s.data.forEach((v,i)=>{{if(v===null){{started=false;return}}if(!started){{ctx.moveTo(x(i),y(v));started=true}}else ctx.lineTo(x(i),y(v))}});ctx.stroke();ctx.setLineDash([]);s.data.forEach((v,i)=>{{if(v===null)return;ctx.fillStyle=s.color;ctx.beginPath();ctx.arc(x(i),y(v),3,0,Math.PI*2);ctx.fill()}})}})}}
function barChart(id,labels,series,title){{const{{ctx,w,h}}=surface(id),pad={{l:46,r:12,t:58,b:35}};ctx.clearRect(0,0,w,h);ctx.fillStyle='#082747';ctx.font='bold 12px Arial';ctx.textAlign='center';ctx.fillText(title,w/2,17);ctx.textAlign='left';legend(ctx,series,w);const max=Math.max(...series.flatMap(s=>s.data))*1.12||1,plotW=w-pad.l-pad.r,group=plotW/labels.length,bar=Math.min(18,group/(series.length+1));ctx.font='10px Arial';for(let i=0;i<5;i++){{const val=max*i/4,yy=h-pad.b-val*(h-pad.t-pad.b)/max;ctx.strokeStyle=palette.grid;ctx.beginPath();ctx.moveTo(pad.l,yy);ctx.lineTo(w-pad.r,yy);ctx.stroke();ctx.fillStyle=palette.text;ctx.textAlign='right';ctx.fillText(fmt(val,0),pad.l-6,yy+3)}}labels.forEach((lab,i)=>{{const center=pad.l+group*(i+.5);ctx.fillStyle=palette.text;ctx.textAlign='center';ctx.fillText(lab,center,h-11);series.forEach((s,j)=>{{const v=s.data[i],bh=v*(h-pad.t-pad.b)/max,x=center+(j-(series.length-1)/2)*bar-bar*.42;ctx.fillStyle=s.color;ctx.fillRect(x,h-pad.b-bh,bar*.84,bh)}})}})}}
function drawBts(){{lineChart('btsChart',DATA.bts.labels,[{{label:'Bản tin 15/08',data:DATA.bts.august,color:palette.gray,dash:[6,5]}},{{label:'Bản tin 15/09',data:DATA.bts.september,color:palette.blue}},{{label:'Mức TBNN',data:DATA.bts.labels.map(()=>0),color:palette.green}}],'Dòng chảy Buôn Tua Srah','%')}}
const select=document.getElementById('scenarioSelect');DATA.scenarios.forEach(x=>select.add(new Option(x.id,x.id)));select.value='PA2a';
function update(){{const x=DATA.scenarios.find(v=>v.id===select.value);[['demandKpi',x.demand],['hydroKpi',x.hydro],['oilKpi',x.oil],['importKpi',x.imports],['shortageKpi',x.shortage]].forEach(([id,v])=>document.getElementById(id).textContent=`${{fmt(v)}} TWh`);document.getElementById('shortageKpi').style.color=x.shortage?palette.red:'#138a4b';document.getElementById('scenarioSummary').textContent=`${{x.id}}: phụ tải tăng ${{fmt(x.growth,2)}}%; thủy văn ${{x.hydrology.toLowerCase()}}. Tổng sản lượng ${{fmt(x.production)}} TWh.`;lineChart('monthlyChart',DATA.months,[{{label:'Phụ tải',data:x.monthlyDemand,color:palette.blue}},{{label:'Thủy điện',data:x.monthlyHydro,color:palette.green}}],`Phụ tải và thủy điện tháng - ${{x.id}}`)}}
function drawScenarios(){{barChart('scenarioChart',DATA.scenarios.map(x=>x.id),[{{label:'Thiếu hụt',data:DATA.scenarios.map(x=>x.shortage),color:palette.red}},{{label:'Nhiệt điện dầu',data:DATA.scenarios.map(x=>x.oil),color:palette.amber}}],'Thiếu hụt và huy động dầu theo phương án')}}
select.addEventListener('change',update);drawBts();update();drawScenarios();let resizeTimer;window.addEventListener('resize',()=>{{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{{drawBts();update();drawScenarios()}},120)}});
</script></body></html>'''
